/**
 * Calculates dynamic reading duration based on word count.
 * Base 5s for comprehension + 350ms per word (~170 WPM).
 * Clamped between 8s minimum and 24s maximum.
 */
export function getDynamicQuoteDuration(quoteText: string): { words: number; sec: number } {
    const words = quoteText.trim().split(/\s+/).filter(Boolean).length;
    const sec = Math.max(8, Math.min(24, Math.round(5 + (words * 0.35))));
    return { words, sec };
}

export class QuotesManager {
    private static welcomeIdx: number = 7; // Default: Thomas Kurian (CEO, Google Cloud)
    private static loadingIdx: number = 1; // Default: Bill Gates
    private static timerInterval: any = null;
    private static currentDuration: number = 17;
    private static timerSeconds: number = 17;

    public static initWelcomeQuote(): void {
        QuotesManager.updateWelcomeCard(QuotesManager.welcomeIdx);

        const btnShuffle = document.getElementById("welcome-quote-shuffle");
        if (btnShuffle) {
            btnShuffle.addEventListener("click", () => {
                QuotesManager.nextWelcomeQuote();
            });
        }
    }

    public static nextWelcomeQuote(): void {
        QuotesManager.welcomeIdx = (QuotesManager.welcomeIdx + 1) % THOUGHT_QUOTES.length;
        QuotesManager.updateWelcomeCard(QuotesManager.welcomeIdx);
    }

    private static updateWelcomeCard(idx: number): void {
        const q = THOUGHT_QUOTES[idx];
        if (!q) return;

        const box = document.getElementById("welcome-quote-box");
        if (box) {
            box.classList.remove("anim-quote-swap");
            void box.offsetWidth; // trigger reflow
            box.classList.add("anim-quote-swap");
        }

        const elText = document.getElementById("welcome-quote-text");
        if (elText) elText.textContent = `\"${q.quote}\"`;

        const elAuthor = document.getElementById("welcome-quote-author");
        if (elAuthor) elAuthor.textContent = q.name;

        const elRole = document.getElementById("welcome-quote-role");
        if (elRole) elRole.textContent = q.role;

        const elCat = document.getElementById("welcome-quote-cat");
        if (elCat) elCat.textContent = q.category;

        const elNetWorth = document.getElementById("welcome-quote-networth");
        if (elNetWorth) elNetWorth.textContent = q.netWorth;

        const elNetWorthDetail = document.getElementById("welcome-quote-networth-detail");
        if (elNetWorthDetail) elNetWorthDetail.textContent = q.netWorth;

        const elIdx = document.getElementById("welcome-quote-idx");
        if (elIdx) elIdx.textContent = String(idx + 1);

        const elAvatar = document.getElementById("welcome-author-avatar");
        if (elAvatar) {
            const initials = q.name.split(" ").map(n => n[0]).join("").slice(0, 2);
            elAvatar.textContent = initials;
        }
    }

    public static startLoadingQuotes(): void {
        // Pick random quote or pick next on each start
        QuotesManager.loadingIdx = Math.floor(Math.random() * THOUGHT_QUOTES.length);
        QuotesManager.updateLoadingCard(QuotesManager.loadingIdx);

        if (QuotesManager.timerInterval) {
            clearInterval(QuotesManager.timerInterval);
        }

        QuotesManager.timerInterval = setInterval(() => {
            const timerEl = document.getElementById("loading-quote-timer");
            const barEl = document.getElementById("loading-quote-progress-bar");
            if (timerEl && barEl) {
                QuotesManager.timerSeconds -= 0.1;
                if (QuotesManager.timerSeconds <= 0) {
                    QuotesManager.nextLoadingQuote();
                } else {
                    timerEl.textContent = Math.ceil(QuotesManager.timerSeconds) + "s";
                    barEl.style.width = Math.max(0, Math.min(100, (QuotesManager.timerSeconds / QuotesManager.currentDuration) * 100)) + "%";
                }
            }
        }, 100);

        const btnNext = document.getElementById("btn-next-loading-quote");
        if (btnNext && !btnNext.dataset.bound) {
            btnNext.dataset.bound = "true";
            btnNext.addEventListener("click", () => {
                QuotesManager.nextLoadingQuote();
            });
        }
    }

    public static stopLoadingQuotes(): void {
        if (QuotesManager.timerInterval) {
            clearInterval(QuotesManager.timerInterval);
            QuotesManager.timerInterval = null;
        }
    }

    public static nextLoadingQuote(): void {
        QuotesManager.loadingIdx = (QuotesManager.loadingIdx + 1) % THOUGHT_QUOTES.length;
        QuotesManager.updateLoadingCard(QuotesManager.loadingIdx);
    }

    private static updateLoadingCard(idx: number): void {
        const q = THOUGHT_QUOTES[idx];
        if (!q) return;

        const dyn = getDynamicQuoteDuration(q.quote);
        QuotesManager.currentDuration = dyn.sec;
        QuotesManager.timerSeconds = dyn.sec;

        const elText = document.getElementById("loading-quote-text");
        if (elText) elText.textContent = `\"${q.quote}\"`;

        const elAuthor = document.getElementById("loading-quote-author");
        if (elAuthor) elAuthor.textContent = q.name;

        const elRole = document.getElementById("loading-quote-role");
        if (elRole) elRole.textContent = q.role;

        const elCat = document.getElementById("loading-quote-cat");
        if (elCat) elCat.textContent = q.category;

        const elNetWorth = document.getElementById("loading-quote-networth");
        if (elNetWorth) elNetWorth.textContent = q.netWorth;

        const elWordCount = document.getElementById("loading-quote-word-count");
        if (elWordCount) elWordCount.textContent = `${dyn.words} words`;

        const timerEl = document.getElementById("loading-quote-timer");
        if (timerEl) timerEl.textContent = `${dyn.sec}s`;

        const barEl = document.getElementById("loading-quote-progress-bar");
        if (barEl) barEl.style.width = "100%";

        const elAvatar = document.getElementById("loading-author-avatar");
        if (elAvatar) {
            const initials = q.name.split(" ").map(n => n[0]).join("").slice(0, 2);
            elAvatar.textContent = initials;
        }
    }
}
